@import url('https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@300;400;500;600&display=swap');

:root {
  --gold-primary: #f5cf7b;
  --gold-dim: rgba(245, 207, 123, 0.75);
  --gold-glow: rgba(245, 207, 123, 0.35);
  --gold-glass: rgba(18, 14, 24, 0.68);
  --gold-border: rgba(245, 207, 123, 0.32);
  --theme-font: 'JetBrains Mono', monospace;
  --stage-width: min(760px, 92vw);
}

body, .Widgets {
  font-family: var(--theme-font) !important;
}

.Overlay {
  background: rgba(5, 7, 14, 0.45) !important;
}

.Greeting {
  display: none !important;
}

.Time {
  font-family: var(--theme-font) !important;
  text-align: center !important;
  margin-bottom: 1.25rem !important;
}

.Time .date, .Time [class*="date"], .Time h2, .Time p {
  font-family: var(--theme-font) !important;
  font-size: 1.2rem !important;
  font-weight: 400 !important;
  letter-spacing: 0.14em !important;
  color: var(--gold-dim) !important;
  text-transform: capitalize !important;
  margin-bottom: 0.25rem !important;
  text-shadow: 0 0 10px var(--gold-glow) !important;
}

.Time h1, .Time .Digital h1 {
  font-family: var(--theme-font) !important;
  font-size: 5rem !important;
  font-weight: 300 !important;
  letter-spacing: 0.16em !important;
  color: var(--gold-primary) !important;
  text-shadow: 0 0 16px var(--gold-glow), 0 2px 14px rgba(0, 0, 0, 0.85) !important;
  margin: 0 !important;
  line-height: 1.1 !important;
}

.Search {
  display: flex !important;
  flex-direction: column !important;
  align-items: center !important;
  width: 100% !important;
  margin: 0 auto 1.6rem auto !important;
}

.Search::before {
  content: 'EARLY SKETCHES \\2022  SOUSOU NO FRIEREN' !important;
  display: flex !important;
  align-items: flex-end !important;
  box-sizing: border-box !important;
  width: var(--stage-width) !important;
  height: 270px !important;
  margin: 0 auto 1.5rem auto !important;
  padding: 1.1rem 1.4rem !important;
  background: linear-gradient(to top, rgba(14, 10, 18, 0.92) 0%, rgba(14, 10, 18, 0.2) 40%, transparent 100%), url('https://images.alphacoders.com/135/thumb-1920-1354383.jpeg') center/cover no-repeat !important;
  border: 1px solid var(--gold-border) !important;
  border-radius: 16px !important;
  box-shadow: 0 12px 35px rgba(0, 0, 0, 0.65) !important;
  font-family: var(--theme-font) !important;
  font-size: 0.72rem !important;
  font-weight: 500 !important;
  letter-spacing: 0.22em !important;
  text-transform: uppercase !important;
  color: rgba(254, 243, 199, 0.88) !important;
  text-shadow: 0 1px 4px rgba(0, 0, 0, 0.95) !important;
}

.Search form {
  width: var(--stage-width) !important;
  max-width: var(--stage-width) !important;
  margin: 0 auto !important;
}

.Search input, .Search input[type="text"], .Search input[type="search"] {
  width: 100% !important;
  height: 44px !important;
  box-sizing: border-box !important;
  font-family: var(--theme-font) !important;
  font-size: 0.9rem !important;
  letter-spacing: 0.08em !important;
  text-align: center !important;
  color: var(--gold-primary) !important;
  background: var(--gold-glass) !important;
  backdrop-filter: blur(14px) !important;
  -webkit-backdrop-filter: blur(14px) !important;
  border: 1px solid var(--gold-border) !important;
  border-radius: 9999px !important;
  padding: 0 1.5rem !important;
  outline: none !important;
  box-shadow: 0 4px 15px rgba(0, 0, 0, 0.4) !important;
  transition: all 0.25s ease !important;
}

.Search input::placeholder {
  color: rgba(245, 207, 123, 0.5) !important;
  opacity: 1 !important;
  letter-spacing: 0.08em !important;
}

.Search input:focus {
  border-color: var(--gold-primary) !important;
  box-shadow: 0 0 20px rgba(245, 207, 123, 0.4), 0 4px 20px rgba(0, 0, 0, 0.5) !important;
  background: rgba(24, 18, 30, 0.85) !important;
}

.Links {
  display: grid !important;
  grid-template-columns: repeat(4, 1fr) !important;
  gap: 0.75rem 2rem !important;
  width: var(--stage-width) !important;
  max-width: var(--stage-width) !important;
  margin: 0 auto !important;
  padding: 0 !important;
  justify-items: start !important;
}

.Links a {
  display: inline-flex !important;
  align-items: center !important;
  font-family: var(--theme-font) !important;
  font-size: 0.92rem !important;
  letter-spacing: 0.06em !important;
  color: var(--gold-dim) !important;
  text-decoration: none !important;
  text-transform: lowercase !important;
  background: transparent !important;
  border: none !important;
  padding: 0.2rem 0 !important;
  transition: all 0.2s ease !important;
}

.Links a img, .Links a svg {
  display: none !important;
}

.Links a::before {
  content: '>\\00a0' !important;
  color: var(--gold-primary) !important;
  font-weight: 600 !important;
  opacity: 0.85 !important;
  transition: all 0.2s ease !important;
}

.Links a:hover {
  color: #fffbeb !important;
  transform: translateX(4px) !important;
  text-shadow: 0 0 10px rgba(245, 207, 123, 0.5) !important;
}

.Links a:hover::before {
  opacity: 1 !important;
  color: #ffffff !important;
}

.Weather {
  font-family: var(--theme-font) !important;
  color: var(--gold-primary) !important;
  letter-spacing: 0.06em !important;
  text-shadow: 0 0 8px var(--gold-glow) !important;
}

.Weather .temp {
  font-size: 1.6rem !important;
  font-weight: 400 !important;
}

.Weather p, .Weather span {
  color: var(--gold-dim) !important;
  font-size: 0.85rem !important;
}
